 /// <summary>Stores notes collected during research.</summary>
 public sealed class Notebook
 {
     private readonly List<string> _notes = [];

     public void Add(string note) => _notes.Add(note);

     public IReadOnlyList<string> Notes => _notes;

     public void Clear() => _notes.Clear();
 }

 /// <summary>Tools available to the research agent.</summary>
 public sealed class ResearchTools(Notebook notebook)
 {
     public Notebook Notebook => notebook;

     [Description("Search the web for information on a query. Returns a list of search result snippets with titles and URLs.")]
     public async Task<string> SearchWeb(
         [Description("The search query to look up")] string query)
     {
         using var http = new HttpClient();
         http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
         http.Timeout = TimeSpan.FromSeconds(15);

         try
         {
             // Use DuckDuckGo instant-answer API (no key required)
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
             var html = await http.GetStringAsync(url);

             var results = ParseSearchResults(html, query);
             return results.Length > 0
                 ? results
                 : $"No results found for '{query}'. Try a different search query.";
         }
         catch (Exception ex)
         {
             return $"Search failed for '{query}': {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note. Use this to record important findings, facts, or quotes discovered during research.")]
     public string SaveNote(
         [Description("The note content to save")] string content,
         [Description("The source URL or reference for this note")] string source)
     {
         var note = $"[Source: {source}] {content}";
         notebook.Add(note);
         Console.ForegroundColor = ConsoleColor.DarkYellow;
         Console.WriteLine($"  📝 Note saved ({notebook.Notes.Count} total)");
         Console.ResetColor();
         return $"Note saved successfully. You now have {notebook.Notes.Count} note(s).";
     }

     [Description("Retrieve all saved research notes collected so far.")]
     public string GetAllNotes()
     {
         if (notebook.Notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n\n", notebook.Notes.Select((n, i) => $"Note {i + 1}: {n}"));
     }

     private static string ParseSearchResults(string html, string query)
     {
         // Extract result snippets from DuckDuckGo HTML response
         var results = new List<string>();
         var snippetMarker = "result__snippet";
         var linkMarker = "result__a";
         var pos = 0;

         while (results.Count < 5 && pos < html.Length)
         {
             var snippetIdx = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
             if (snippetIdx < 0) break;

             // Find the snippet text
             var textStart = html.IndexOf('>', snippetIdx);
             if (textStart < 0) break;
             textStart++;

             var textEnd = html.IndexOf('<', textStart);
             if (textEnd < 0) break;

             var snippet = StripHtml(html[textStart..textEnd]).Trim();

             // Look backwards for the link
             var linkStart = html.LastIndexOf(linkMarker, snippetIdx, StringComparison.Ordinal);
             var url = "";
             if (linkStart >= 0)
             {
                 var hrefIdx = html.IndexOf("href=\"", linkStart, StringComparison.Ordinal);
                 if (hrefIdx >= 0 && hrefIdx < snippetIdx)
                 {
                     hrefIdx += 6;
                     var hrefEnd = html.IndexOf('"', hrefIdx);
                     if (hrefEnd > hrefIdx)
                         url = html[hrefIdx..hrefEnd];
                 }

                 // Get the link title text
                 var titleStart = html.IndexOf('>', linkStart);
                 if (titleStart >= 0 && titleStart < snippetIdx)
                 {
                     titleStart++;
                     var titleEnd = html.IndexOf('<', titleStart);
                     if (titleEnd > titleStart)
                     {
                         var title = StripHtml(html[titleStart..titleEnd]).Trim();
                         if (snippet.Length > 0 || title.Length > 0)
                         {
                             results.Add($"Title: {title}\nURL: {url}\nSnippet: {snippet}");
                         }
                     }
                 }
             }

             pos = textEnd;
         }

         return results.Count > 0
             ? $"Search results for '{query}':\n\n" + string.Join("\n---\n", results)
             : "";
     }

     private static string StripHtml(string text)
     {
         return System.Text.RegularExpressions.Regex.Replace(
             System.Net.WebUtility.HtmlDecode(text), "<[^>]+>", "");
     }
 }
